import socket


class IpUtil:

    IPV4_FAMILY = socket.AF_INET
    IPV6_FAMILY = socket.AF_INET6

    @staticmethod
    def is_valid_ipv4(ip_address):
        return IpUtil._validate_ip(ip_address, IpUtil.IPV4_FAMILY)

    @staticmethod
    def is_valid_ipv6(ip_address):
        return IpUtil._validate_ip(ip_address, IpUtil.IPV6_FAMILY)

    @staticmethod
    def _validate_ip(ip_address, address_family):
        try:
            socket.inet_pton(address_family, ip_address)
            return True
        except socket.error:
            return False

    @staticmethod
    def get_hostname(ip_address):
        try:
            return socket.gethostbyaddr(ip_address)[0]
        except socket.herror:
            return None
